WallpaperVideo::~WallpaperVideo(){stop();}
void WallpaperVideo::stop(){stopping=true;wake.notify_all();if(worker.joinable())worker.join();running=false;std::lock_guard<std::mutex> lock(mutex);frame={};}
void WallpaperVideo::pause(bool value){paused=value;wake.notify_all();}
WallpaperFrame WallpaperVideo::latest()const{std::lock_guard<std::mutex> lock(mutex);return frame;}
std::string WallpaperVideo::error()const{std::lock_guard<std::mutex> lock(mutex);return problem;}
void WallpaperVideo::start(const std::filesystem::path& path,int fps){if(fps!=15&&fps!=24&&fps!=30)throw std::runtime_error("Wallpaper frame cap must be 15, 24 or 30");if(!path.is_absolute()||!std::filesystem::is_regular_file(path)||lower(utf8(path.extension().wstring()))!=".mp4"||std::filesystem::file_size(path)>2ULL*1024*1024*1024)throw std::runtime_error("Choose an existing local MP4 no larger than 2 GB");stop();stopping=false;paused=false;running=true;{std::lock_guard<std::mutex> lock(mutex);problem.clear();}
    worker=std::thread([this,path,fps]{try{Apartment apartment;check_hr(MFStartup(MF_VERSION),"Wallpaper Media Foundation");struct End{~End(){MFShutdown();}} end;Com<IMFAttributes> attrs;check_hr(MFCreateAttributes(&attrs.p,2),"Wallpaper attributes");attrs->SetUINT32(MF_SOURCE_READER_ENABLE_VIDEO_PROCESSING,TRUE);Com<IMFSourceReader> reader;check_hr(MFCreateSourceReaderFromURL(path.c_str(),attrs.p,&reader.p),"Read wallpaper video");check_hr(reader->SetStreamSelection(MF_SOURCE_READER_ALL_STREAMS,FALSE),"Wallpaper streams");check_hr(reader->SetStreamSelection(MF_SOURCE_READER_FIRST_VIDEO_STREAM,TRUE),"Wallpaper video stream");Com<IMFMediaType> native;check_hr(reader->GetNativeMediaType(MF_SOURCE_READER_FIRST_VIDEO_STREAM,0,&native.p),"Wallpaper native format");UINT32 width=0,height=0;check_hr(MFGetAttributeSize(native.p,MF_MT_FRAME_SIZE,&width,&height),"Wallpaper dimensions");if(!width||!height||width>3840||height>2160)throw std::runtime_error("Video wallpaper supports up to 3840 x 2160; use a smaller local clip");Com<IMFMediaType> output;check_hr(MFCreateMediaType(&output.p),"Wallpaper output");output->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Video);output->SetGUID(MF_MT_SUBTYPE,MFVideoFormat_RGB32);check_hr(reader->SetCurrentMediaType(MF_SOURCE_READER_FIRST_VIDEO_STREAM,nullptr,output.p),"Wallpaper RGB decode");Com<IMFMediaType> actual;check_hr(reader->GetCurrentMediaType(MF_SOURCE_READER_FIRST_VIDEO_STREAM,&actual.p),"Wallpaper decoded format");MFGetAttributeSize(actual.p,MF_MT_FRAME_SIZE,&width,&height);LONG stride=static_cast<LONG>(width*4);UINT32 stored=0;if(SUCCEEDED(actual->GetUINT32(MF_MT_DEFAULT_STRIDE,&stored)))stride=static_cast<LONG>(stored);auto next=std::chrono::steady_clock::now();LONGLONG first=-1,previous=-1;unsigned long long sequence=0;
        while(!stopping){if(paused){std::unique_lock<std::mutex> lock(mutex);wake.wait_for(lock,std::chrono::milliseconds(100),[&]{return stopping.load()||!paused.load();});first=-1;continue;}DWORD stream=0,flags=0;LONGLONG timestamp=0;Com<IMFSample> sample;check_hr(reader->ReadSample(MF_SOURCE_READER_FIRST_VIDEO_STREAM,0,&stream,&flags,&timestamp,&sample.p),"Wallpaper frame");if(flags&MF_SOURCE_READERF_CURRENTMEDIATYPECHANGED){Com<IMFMediaType> changed;check_hr(reader->GetCurrentMediaType(MF_SOURCE_READER_FIRST_VIDEO_STREAM,&changed.p),"Wallpaper negotiated format");GUID subtype{};changed->GetGUID(MF_MT_SUBTYPE,&subtype);check_hr(MFGetAttributeSize(changed.p,MF_MT_FRAME_SIZE,&width,&height),"Wallpaper negotiated dimensions");if(subtype!=MFVideoFormat_RGB32||!width||!height||width>3840||height>2160)throw std::runtime_error("Wallpaper decoder negotiated an unsupported frame format");stride=static_cast<LONG>(width*4);UINT32 value=0;if(SUCCEEDED(changed->GetUINT32(MF_MT_DEFAULT_STRIDE,&value)))stride=static_cast<LONG>(value);}if(flags&MF_SOURCE_READERF_ENDOFSTREAM){PROPVARIANT position{};position.vt=VT_I8;position.hVal.QuadPart=0;check_hr(reader->SetCurrentPosition(GUID_NULL,position),"Loop wallpaper");first=-1;previous=-1;continue;}if(!sample.p)continue;if(first<0){first=timestamp;next=std::chrono::steady_clock::now();}if(previous>=0&&timestamp-previous<10000000/fps)continue;previous=timestamp;auto due=next+std::chrono::nanoseconds((timestamp-first)*100);while(!stopping&&!paused&&std::chrono::steady_clock::now()<due){std::unique_lock<std::mutex> lock(mutex);wake.wait_for(lock,std::chrono::milliseconds(8));}if(stopping)break;if(paused)continue;Com<IMFMediaBuffer> buffer;check_hr(sample->ConvertToContiguousBuffer(&buffer.p),"Wallpaper pixels");BYTE* bytes=nullptr;DWORD length=0;check_hr(buffer->Lock(&bytes,nullptr,&length),"Wallpaper pixel lock");struct Unlock{IMFMediaBuffer* p;~Unlock(){p->Unlock();}} unlock{buffer.p};auto pitch=static_cast<size_t>(std::abs(stride));if(pitch<width*4||length<pitch*height)throw std::runtime_error("Wallpaper decoder returned incomplete pixels");WallpaperFrame value;value.width=width;value.height=height;value.sequence=++sequence;value.pixels.resize(static_cast<size_t>(width)*height*4);for(UINT32 y=0;y<height;++y){auto source_y=stride<0?height-1-y:y;memcpy(value.pixels.data()+static_cast<size_t>(y)*width*4,bytes+source_y*pitch,width*4);}std::lock_guard<std::mutex> lock(mutex);frame=std::move(value);}
    }catch(const std::exception& e){std::lock_guard<std::mutex> lock(mutex);problem=e.what();}running=false;});
}
int desktop_volume(){Apartment apartment;Com<IMMDeviceEnumerator> devices;Com<IMMDevice> device;Com<IAudioEndpointVolume> volume;check_hr(CoCreateInstance(__uuidof(MMDeviceEnumerator),nullptr,CLSCTX_INPROC_SERVER,__uuidof(IMMDeviceEnumerator),reinterpret_cast<void**>(&devices.p)),"Volume devices");check_hr(devices->GetDefaultAudioEndpoint(eRender,eConsole,&device.p),"Default output");check_hr(device->Activate(__uuidof(IAudioEndpointVolume),CLSCTX_INPROC_SERVER,nullptr,reinterpret_cast<void**>(&volume.p)),"Output volume");float value=0;check_hr(volume->GetMasterVolumeLevelScalar(&value),"Read system volume");return static_cast<int>(std::lround(value*100));}
void desktop_set_volume(int percent){if(percent<0||percent>100)throw std::runtime_error("Volume must be 0..100");Apartment apartment;Com<IMMDeviceEnumerator> devices;Com<IMMDevice> device;Com<IAudioEndpointVolume> volume;check_hr(CoCreateInstance(__uuidof(MMDeviceEnumerator),nullptr,CLSCTX_INPROC_SERVER,__uuidof(IMMDeviceEnumerator),reinterpret_cast<void**>(&devices.p)),"Volume devices");check_hr(devices->GetDefaultAudioEndpoint(eRender,eConsole,&device.p),"Default output");check_hr(device->Activate(__uuidof(IAudioEndpointVolume),CLSCTX_INPROC_SERVER,nullptr,reinterpret_cast<void**>(&volume.p)),"Output volume");check_hr(volume->SetMasterVolumeLevelScalar(percent/100.0f,nullptr),"Set system volume");}
DesktopAudioMeter::~DesktopAudioMeter(){stop();}
void DesktopAudioMeter::stop(){stopping=true;if(worker.joinable())worker.join();peak=0;for(auto& value:bins)value=0;}
std::string DesktopAudioMeter::error()const{std::lock_guard<std::mutex> lock(mutex);return problem;}
void DesktopAudioMeter::start(){stop();stopping=false;{std::lock_guard<std::mutex> lock(mutex);problem.clear();}worker=std::thread([this]{try{Apartment apartment;Com<IMMDeviceEnumerator> devices;Com<IMMDevice> device;Com<IAudioClient> client;Com<IAudioCaptureClient> capture;check_hr(CoCreateInstance(__uuidof(MMDeviceEnumerator),nullptr,CLSCTX_INPROC_SERVER,__uuidof(IMMDeviceEnumerator),reinterpret_cast<void**>(&devices.p)),"System audio devices");check_hr(devices->GetDefaultAudioEndpoint(eRender,eConsole,&device.p),"System playback endpoint");check_hr(device->Activate(__uuidof(IAudioClient),CLSCTX_INPROC_SERVER,nullptr,reinterpret_cast<void**>(&client.p)),"System audio client");WAVEFORMATEX* raw=nullptr;check_hr(client->GetMixFormat(&raw),"System mix format");std::unique_ptr<WAVEFORMATEX,decltype(&CoTaskMemFree)> format(raw,&CoTaskMemFree);check_hr(client->Initialize(AUDCLNT_SHAREMODE_SHARED,AUDCLNT_STREAMFLAGS_LOOPBACK,1000000,0,format.get(),nullptr),"System audio level stream");check_hr(client->GetService(__uuidof(IAudioCaptureClient),reinterpret_cast<void**>(&capture.p)),"System audio capture");check_hr(client->Start(),"Start system audio levels");struct Stop{IAudioClient* p;~Stop(){p->Stop();}} stop{client.p};while(!stopping){UINT32 available=0;check_hr(capture->GetNextPacketSize(&available),"Audio level packet");double highest=0;while(available&&!stopping){BYTE* bytes=nullptr;UINT32 frames=0;DWORD flags=0;check_hr(capture->GetBuffer(&bytes,&frames,&flags,nullptr,nullptr),"Audio level buffer");try{highest=std::max(highest,measure_audio(bytes,frames,*format,(flags&AUDCLNT_BUFFERFLAGS_SILENT)!=0).peak);for(size_t n=0;n<32;++n){auto first=frames*n/32,count=frames*(n+1)/32-first;float value=count?static_cast<float>(measure_audio(bytes?bytes+first*format->nBlockAlign:nullptr,count,*format,(flags&AUDCLNT_BUFFERFLAGS_SILENT)!=0).peak):0;bins[n]=std::max(value,bins[n].load()*.82f);}}catch(...){capture->ReleaseBuffer(frames);throw;}capture->ReleaseBuffer(frames);capture->GetNextPacketSize(&available);}peak=std::max(highest,peak.load()*.85);if(!highest)for(auto& value:bins)value=value.load()*.82f;Sleep(20);}}catch(const std::exception& e){peak=0;for(auto& value:bins)value=0;std::lock_guard<std::mutex> lock(mutex);problem=e.what();}});}
DesktopWeather parse_desktop_weather(const std::string& json){if(json.empty()||json.size()>262144)throw std::runtime_error("Weather response exceeds limits");auto marker=json.find("\"current\"");if(marker==std::string::npos)throw std::runtime_error("Weather service returned no current data");auto begin=json.find('{',marker),end=json.find('}',begin);if(begin==std::string::npos||end==std::string::npos)throw std::runtime_error("Invalid current weather record");auto data=json.substr(begin,end-begin+1);auto number=[&](const std::string& name){std::smatch match;if(!std::regex_search(data,match,std::regex("\\\""+name+"\\\"\\s*:\\s*(-?[0-9]+(?:\\.[0-9]+)?)")))throw std::runtime_error("Missing current weather value");return std::stod(match[1]);};DesktopWeather result;result.temperature=number("temperature_2m");result.wind=number("wind_speed_10m");result.code=static_cast<int>(number("weather_code"));std::smatch time;if(std::regex_search(data,time,std::regex("\\\"time\\\"\\s*:\\s*\\\"([^\\\"]{1,40})\\\"")))result.time=time[1];if(!std::isfinite(result.temperature)||result.temperature< -100||result.temperature>70||!std::isfinite(result.wind)||result.wind<0||result.wind>500||result.code<0||result.code>99)throw std::runtime_error("Weather service returned invalid measurements");return result;}
std::string weather_description(int c){if(c==0)return "Clear";if(c<=3)return "Cloudy";if(c==45||c==48)return "Fog";if(c>=51&&c<=57)return "Drizzle";if(c>=61&&c<=67)return "Rain";if(c>=71&&c<=77)return "Snow";if(c>=80&&c<=82)return "Rain showers";if(c==85||c==86)return "Snow showers";if(c>=95)return "Thunderstorm";return "Weather code "+std::to_string(c);}
DesktopWeatherClient::~DesktopWeatherClient(){if(worker.joinable())worker.join();}
void DesktopWeatherClient::refresh(double latitude,double longitude){if(!std::isfinite(latitude)||!std::isfinite(longitude)||latitude< -90||latitude>90||longitude< -180||longitude>180)throw std::runtime_error("Enter valid latitude and longitude");if(busy)throw std::runtime_error("Weather refresh is already running");if(worker.joinable())worker.join();busy=true;{std::lock_guard<std::mutex> lock(mutex);problem="Refreshing Open-Meteo current conditions...";}worker=std::thread([this,latitude,longitude]{try{Http session{WinHttpOpen(L"NovaTune Desktop/2.0",WINHTTP_ACCESS_TYPE_DEFAULT_PROXY,WINHTTP_NO_PROXY_NAME,WINHTTP_NO_PROXY_BYPASS,0)};if(!session.h)throw std::runtime_error("Weather connection unavailable");WinHttpSetTimeouts(session.h,3000,3000,5000,5000);Http connection{WinHttpConnect(session.h,L"api.open-meteo.com",INTERNET_DEFAULT_HTTPS_PORT,0)};if(!connection.h)throw std::runtime_error("Weather host unavailable");std::wostringstream path;path.imbue(std::locale::classic());path<<L"/v1/forecast?latitude="<<std::fixed<<std::setprecision(4)<<latitude<<L"&longitude="<<longitude<<L"&current=temperature_2m,weather_code,wind_speed_10m&timezone=auto&forecast_days=1";Http request{WinHttpOpenRequest(connection.h,L"GET",path.str().c_str(),nullptr,WINHTTP_NO_REFERER,WINHTTP_DEFAULT_ACCEPT_TYPES,WINHTTP_FLAG_SECURE)};if(!request.h||!WinHttpSendRequest(request.h,WINHTTP_NO_ADDITIONAL_HEADERS,0,WINHTTP_NO_REQUEST_DATA,0,0,0)||!WinHttpReceiveResponse(request.h,nullptr))throw std::runtime_error("Weather request failed; check the internet connection");DWORD status=0,size=sizeof status;WinHttpQueryHeaders(request.h,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,WINHTTP_HEADER_NAME_BY_INDEX,&status,&size,WINHTTP_NO_HEADER_INDEX);if(status!=200)throw std::runtime_error("Weather service returned HTTP "+std::to_string(status));std::string body;for(;;){char bytes[8192];DWORD read=0;if(!WinHttpReadData(request.h,bytes,sizeof bytes,&read))throw std::runtime_error("Weather response was interrupted");if(!read)break;body.append(bytes,read);if(body.size()>262144)throw std::runtime_error("Weather response exceeds limits");}auto value=parse_desktop_weather(body);std::lock_guard<std::mutex> lock(mutex);reading=value;valid=true;problem.clear();}catch(const std::exception& e){std::lock_guard<std::mutex> lock(mutex);problem=e.what();}busy=false;});}
std::string DesktopWeatherClient::text()const{std::lock_guard<std::mutex> lock(mutex);std::ostringstream out;if(valid){out<<std::fixed<<std::setprecision(1)<<reading.temperature<<" C / "<<weather_description(reading.code)<<"\nWind "<<reading.wind<<" km/h / "+reading.time+"\nOpen-Meteo";if(!problem.empty())out<<"\nLast reading retained; "<<problem;}else out<<problem;return out.str();}
